INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 11, 'theory', 'Quiz: built-in functions');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 11, 0, 'What are ROUND(2.5) and ROUND(-2.5) in SQLite?', '["2 and −2", "3 and −3", "3 and −2", "2 and −3"]', 1, 'SQLite rounds halves "away from zero": 2.5 → 3, −2.5 → −3. Banker''s rounding to the nearest even number is not used.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 11, 1, 'How do you get the start of the current month?', '["DATE(''now'', ''start of month'')", "DATE(''now'', ''-1 month'')", "STRFTIME(''%m'')", "DATE(''start of month'')"]', 0, 'The ''start of month'' modifier moves the date to the first day of the month. It can be combined with others: DATE(''now'', ''start of month'', ''-1 month'').');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 11, 2, 'How do you count the days between two dates a and b?', '["a - b", "JULIANDAY(a) - JULIANDAY(b)", "STRFTIME(''%d'', a - b)", "DATE(a, b)"]', 1, 'Dates are strings and cannot be subtracted directly. JULIANDAY turns a date into a number of days, and the difference of those numbers is the count you want.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 11, 3, 'What does DATE(''05.05.2024'') return?', '["2024-05-05", "NULL", "An error", "The current date"]', 1, 'Date functions recognize only ISO formats; for an unrecognized string the result is NULL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 11, 4, 'How do you get the month key "2024-05" from a date d?', '["STRFTIME(''%Y-%m'', d)", "MONTH(d)", "SUBSTR(d, 5)", "DATE(d, ''%Y-%m'')"]', 0, 'STRFTIME with the format ''%Y-%m'' returns the year and month as a string, a convenient key for GROUP BY. SUBSTR(d, 1, 7) also works, but it does not validate the format.');
